using System;
using System.IO;
using System.IO.Compression;

public static class ArchiveExtractor
{
    public static void Extract(Stream input, string destinationRoot)
    {
        const int maxEntries = 100;
        const long maxExpandedBytes = 1_000_000;
        const double maxCompressionRatio = 10;
        long expandedBytes = 0;
        var entries = 0;

        using var archive = new ZipArchive(input, ZipArchiveMode.Read, leaveOpen: true);
        foreach (var entry in archive.Entries)
        {
            if (++entries > maxEntries || entry.Length > maxExpandedBytes - expandedBytes)
                throw new InvalidDataException("archive expansion limit exceeded");

            var ratio = entry.CompressedLength == 0
                ? double.PositiveInfinity
                : (double)entry.Length / entry.CompressedLength;
            if (ratio > maxCompressionRatio)
                throw new InvalidDataException("archive compression ratio exceeded");

            var destination = Path.Combine(destinationRoot, entry.Name);
            expandedBytes += CopyEntry(entry, destination, expandedBytes, maxExpandedBytes);
        }
    }

    private static long CopyEntry(ZipArchiveEntry entry, string destination, long expandedBytes, long maxExpandedBytes)
    {
        using var source = entry.Open();
        var copied = 0L;
        var completed = false;
