using System.IO;
using System.IO.Compression;

public static class ArchiveFlowSafe
{
    public static void Expand(Stream untrustedArchive, string destination)
    {
        const int maxEntries = 100;
        const long maxExpandedBytes = 1_000_000;
        const double maxCompressionRatio = 10;
        var count = 0;
        long total = 0;
        using var archive = new ZipArchive(untrustedArchive, ZipArchiveMode.Read);
        foreach (var entry in archive.Entries)
        {
            if (++count > maxEntries || entry.Length > maxExpandedBytes - total)
                throw new InvalidDataException("archive expansion limit exceeded");
            var ratio = entry.CompressedLength == 0
                ? double.PositiveInfinity
                : (double)entry.Length / entry.CompressedLength;
            if (ratio > maxCompressionRatio)
                throw new InvalidDataException("archive compression ratio exceeded");

            var outputPath = Path.Combine(destination, entry.Name);
            total += CopyEntry(entry, outputPath, total, maxExpandedBytes);
        }
    }

    private static long CopyEntry(ZipArchiveEntry entry, string outputPath, long total, long maxExpandedBytes)
    {
        using var source = entry.Open();
        var copied = 0L;
        var completed = false;
        try
        {
            using (var output = new FileStream(outputPath, FileMode.Create, FileAccess.Write, FileShare.None))
            {
                var buffer = new byte[81920];
                int read;
                while ((read = source.Read(buffer, 0, buffer.Length)) > 0)
                {
                    if (read > maxExpandedBytes - total - copied)
                        throw new InvalidDataException("archive expansion limit exceeded");
                    output.Write(buffer, 0, read);
                    copied += read;
                }
